# Try to find the functions at our addresses using objdump
for addr in 0x222098 0x222234 0x19bac0 0x19bc14; do
  echo "=== $addr ==="
  # Find the nearest symbol below this address
  nm -D --defined-only libmonosgen-2.0.so 2>/dev/null | sort | awk -v target="$addr" '
    BEGIN { gsub("0x","",target) }
    {
      if ($2 == "T" || $2 == "t" || $2 == "W" || $2 == "w") {
        if ("0x" $1 <= target) { name=$3; saddr=$1 }
      }
    }
    END { if (name) print name " (+" target " - " saddr ")" ; else print "unknown" }
  '
done

