arguments.command:
cd /tmp/sv-759f1dfa569342ba8aeb60947c1fb93c/symbols && \
# Properly find nearest symbols using Python
python3 -c "
import subprocess, re

# Get all defined text symbols
result = subprocess.run(['nm', '-D', '--defined-only', 'libmonosgen-2.0.so'], capture_output=True, text=True)
symbols = []
for line in result.stdout.strip().split('\n'):
    parts = line.split()
    if len(parts) >= 3 and parts[1] in ('T', 't', 'W', 'w'):
        symbols.append((int(parts[0], 16), parts[2]))
symbols.sort()

# Addresses to look up (from tombstone)
addrs = {
    'libmonosgen-2.0.so': [
        (0x222098, '#01'),
        (0x222234, '#02'),
        (0x19bac0, '#03'),
        (0x19bc14, '#06'),
    ],
}

for lib, lookups in addrs.items():
    for addr, frame in lookups:
        # Binary search for nearest symbol <= addr
        lo, hi = 0, len(symbols) - 1
        best = None
        while lo <= hi:
            mid = (lo + hi) // 2
            if symbols[mid][0] <= addr:
                best = mid
                lo = mid + 1
            else:
                hi = mid - 1
        if best is not None:
            saddr, sname = symbols[best]
            offset = addr - saddr
            print(f'{frame} pc {addr:#010x} -> {sname}+0x{offset:x}')
        else:
            print(f'{frame} pc {addr:#010x} -> (unknown)')
"

